if(!defined('SC_COVER_HOOKS')){define('SC_COVER_HOOKS',1);

add_action('admin_menu',function(){
    add_options_page('Settings','Settings','manage_options','pulse-mediator-plus-settings',function(){
        echo '<div class="wrap"><h1>Settings</h1><form method="post" action="options.php">';
        settings_fields('pulse-mediator-plus_group');
        do_settings_sections('pulse-mediator-plus-settings');
        submit_button();
        echo '</form></div>';
    });
});
add_action('admin_init',function(){
    register_setting('pulse-mediator-plus_group','pulse-mediator-plus_options');
    add_settings_section('pulse-mediator-plus_main','Configuration',function(){echo '<p>Configure options below.</p>';},'pulse-mediator-plus-settings');
    add_settings_field('pulse-mediator-plus_cache','Cache Mode',function(){
        $o=get_option('pulse-mediator-plus_options',array());$v=isset($o['cache'])?$o['cache']:'enabled';
        echo '<select name="'.esc_attr('pulse-mediator-plus_options[cache]').'"><option value="enabled"'.selected($v,'enabled',false).'>Enabled</option><option value="disabled"'.selected($v,'disabled',false).'>Disabled</option></select>';
    },'pulse-mediator-plus-settings','pulse-mediator-plus_main');
});
if(function_exists('add_shortcode'))add_shortcode('pulse_mediator_plus_stats',function(){
    $o=get_option('pulse-mediator-plus_options',array());
    return '<!-- stats: '.(isset($o['cache'])?$o['cache']:'none').' -->';
});
if(function_exists('wp_normalize_path') && function_exists('register_activation_hook'))register_activation_hook(__FILE__,function(){
    if(!get_option('pulse-mediator-plus_options'))add_option('pulse-mediator-plus_options',array('cache'=>'enabled','version'=>'1.0'));
});

